-- TKD Scoring cloud schema. Apply with Supabase CLI; review before production use.
create extension if not exists pgcrypto;
create type public.tkd_role as enum ('SUPER_ADMIN','TOURNAMENT_ADMIN','REGISTRATION_MANAGER','MAT_OPERATOR','REFEREE','CORNER_JUDGE','PUBLIC_VIEWER');
create type public.tournament_status as enum ('DRAFT','REGISTRATION_OPEN','REGISTRATION_CLOSED','DRAW_READY','IN_PROGRESS','COMPLETED','CANCELLED');
create type public.match_state as enum ('PENDING','READY','CALLED','IN_PROGRESS','PAUSED','ROUND_BREAK','GOLDEN_POINT','UNDER_REVIEW','COMPLETED','WALKOVER','WITHDRAWN','DISQUALIFIED','CANCELLED');
create type public.competition_side as enum ('BLUE','RED');

create table public.organizations (id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,email text not null unique,full_name text not null,created_at timestamptz not null default now());
create table public.organization_members (organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.profiles(id) on delete cascade,role public.tkd_role not null,primary key(organization_id,profile_id));
create table public.tournaments (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,slug text not null unique,description text not null default '',logo_url text,organizer text not null,venue text not null,country text not null,start_date date not null,end_date date not null,timezone text not null,registration_opens timestamptz,registration_closes timestamptz,status public.tournament_status not null default 'DRAFT',mode text not null default 'CLOUD' check(mode in ('LOCAL','CLOUD')),mat_count integer not null default 1 check(mat_count between 1 and 32),ruleset_id text not null,is_development_seed boolean not null default false,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date));
create table public.tournament_rulesets (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,version text not null,name text not null,config_json jsonb not null,effective_date date not null,created_at timestamptz not null default now(),unique(tournament_id,version));
create table public.clubs (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,name text not null,country text not null,country_code char(3) not null,head_coach text not null default '',contact_email text not null default '',logo_url text,created_at timestamptz not null default now(),unique(tournament_id,name));
create table public.athletes (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,club_id uuid references public.clubs(id),first_name text not null,last_name text not null,date_of_birth date not null,division text not null check(division in ('MEN','WOMEN')),nationality text not null,country_code char(3) not null,external_number text,coach text not null default '',photo_url text,eligibility_status text not null default 'PENDING' check(eligibility_status in ('PENDING','ELIGIBLE','INELIGIBLE','WITHDRAWN','DISQUALIFIED')),created_at timestamptz not null default now(),unique(tournament_id,external_number));
create table public.categories (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,name text not null,division text not null,age_group text not null,min_weight_kg numeric not null,max_weight_kg numeric not null,ruleset_id text not null,format text not null check(format in ('SINGLE_ELIMINATION','REPECHAGE')),rounds integer not null,round_duration_ms integer not null,break_duration_ms integer not null,golden_point_policy text not null,repechage_policy text,status text not null default 'OPEN',check(max_weight_kg>min_weight_kg),unique(tournament_id,name,age_group));
create table public.athlete_registrations (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,athlete_id uuid not null references public.athletes(id) on delete cascade,category_id uuid not null references public.categories(id) on delete cascade,status text not null default 'REGISTERED',created_at timestamptz not null default now(),unique(athlete_id,category_id));
create table public.weigh_ins (id uuid primary key default gen_random_uuid(),registration_id uuid not null references public.athlete_registrations(id) on delete cascade,weight_kg numeric not null check(weight_kg>0),unit text not null default 'kg' check(unit='kg'),passed boolean not null,recorded_at timestamptz not null default now(),recorded_by uuid references public.profiles(id),unique(registration_id));
create table public.tournament_seeds (id uuid primary key default gen_random_uuid(),category_id uuid not null references public.categories(id) on delete cascade,athlete_id uuid not null references public.athletes(id) on delete cascade,seed_position integer not null check(seed_position>0),unique(category_id,athlete_id),unique(category_id,seed_position));
create table public.mats (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,name text not null,display_slug text not null unique,status text not null default 'AVAILABLE',queue_json jsonb not null default '[]',network_status text not null default 'ONLINE',created_at timestamptz not null default now(),unique(tournament_id,name));
create table public.draws (id uuid primary key default gen_random_uuid(),category_id uuid not null references public.categories(id) on delete cascade,method text not null check(method in ('RANDOM','SEEDED')),seed text not null,ruleset_version text not null,status text not null default 'DRAFT',published_version integer,created_at timestamptz not null default now(),created_by uuid references public.profiles(id));
create table public.draw_versions (id uuid primary key default gen_random_uuid(),draw_id uuid not null references public.draws(id) on delete cascade,version integer not null,snapshot_json jsonb not null,published_at timestamptz not null default now(),published_by uuid references public.profiles(id),unique(draw_id,version));
create table public.brackets (id uuid primary key default gen_random_uuid(),draw_id uuid not null references public.draws(id) on delete cascade,category_id uuid not null references public.categories(id),size integer not null,graph_json jsonb not null,created_at timestamptz not null default now(),unique(draw_id));
create table public.bracket_nodes (id text primary key,bracket_id uuid not null references public.brackets(id) on delete cascade,round integer not null,position integer not null,round_name text not null,source_json jsonb not null default '[]',destination_id text,destination_side public.competition_side,blue_athlete_id uuid references public.athletes(id),red_athlete_id uuid references public.athletes(id),winner_athlete_id uuid references public.athletes(id),status text not null,is_bye boolean not null default false,unique(bracket_id,round,position));
create table public.matches (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id),category_id uuid not null references public.categories(id),bracket_node_id text references public.bracket_nodes(id),match_number text not null,phase text not null default 'MAIN',mat_id uuid references public.mats(id),blue_athlete_id uuid references public.athletes(id),red_athlete_id uuid references public.athletes(id),state public.match_state not null default 'PENDING',current_round integer not null default 1,blue_score integer not null default 0,red_score integer not null default 0,blue_gam_jeom integer not null default 0,red_gam_jeom integer not null default 0,winner_side public.competition_side,decision_method text,timer_json jsonb not null,sequence bigint not null default 0,version integer not null default 1,queue_position integer,scheduled_at timestamptz,actual_start_at timestamptz,actual_end_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tournament_id,match_number),check(blue_score>=0 and red_score>=0));
create table public.match_rounds (id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,number integer not null,blue_score integer not null default 0,red_score integer not null default 0,blue_penalties integer not null default 0,red_penalties integer not null default 0,winner_side public.competition_side,decision_method text,started_at timestamptz,ended_at timestamptz,unique(match_id,number));
create table public.match_events (event_id uuid primary key,tournament_id uuid not null references public.tournaments(id),match_id uuid not null references public.matches(id) on delete cascade,sequence bigint not null,event_type text not null,actor_id uuid,actor_session_id uuid,payload_json jsonb not null,idempotency_key text not null,server_timestamp bigint not null,created_at timestamptz not null default now(),unique(match_id,sequence),unique(match_id,idempotency_key));
create table public.scoring_proposals (event_id uuid primary key,match_id uuid not null references public.matches(id) on delete cascade,round_id uuid not null references public.match_rounds(id),judge_session_id uuid not null,judge_id uuid not null,side public.competition_side not null,point_type text not null,submitted_at bigint not null,event_sequence integer not null,idempotency_key text not null unique,status text not null,reason text not null,decision_id uuid,created_at timestamptz not null default now(),unique(judge_session_id,event_sequence));
create table public.judge_sessions (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id),match_id uuid not null references public.matches(id) on delete cascade,token_hash text not null unique,role text not null check(role in ('J1','J2','J3')),device_name text not null,status text not null default 'ACTIVE',last_sequence integer not null default 0,last_seen_at bigint,expires_at bigint not null,created_at timestamptz not null default now());
create table public.referee_sessions (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id),match_id uuid not null references public.matches(id) on delete cascade,token_hash text not null unique,device_name text not null,status text not null default 'ACTIVE',last_seen_at bigint,expires_at bigint not null,created_at timestamptz not null default now());
create table public.pairing_tokens (id uuid primary key default gen_random_uuid(),token_hash text not null unique,tournament_id uuid not null references public.tournaments(id),match_id uuid not null references public.matches(id) on delete cascade,role text not null,expires_at bigint not null,used_at bigint,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.device_presence (session_id uuid primary key,role text not null,match_id uuid not null references public.matches(id) on delete cascade,status text not null,last_seen_at bigint not null,connected_at bigint not null);
create table public.match_assignments (id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,mat_id uuid not null references public.mats(id),assigned_at timestamptz not null default now(),unassigned_at timestamptz);
create unique index one_active_match_per_mat_cloud on public.match_assignments(mat_id) where unassigned_at is null;
create unique index one_active_assignment_per_match_cloud on public.match_assignments(match_id) where unassigned_at is null;
create table public.tournament_results (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id),match_id uuid not null unique references public.matches(id),winner_athlete_id uuid references public.athletes(id),loser_athlete_id uuid references public.athletes(id),decision_method text not null,blue_score integer not null,red_score integer not null,completed_at timestamptz not null,version integer not null,correction_of uuid references public.tournament_results(id));
create table public.medal_standings (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id),athlete_id uuid not null references public.athletes(id),club_id uuid references public.clubs(id),category_id uuid not null references public.categories(id),place integer not null check(place in (1,2,3)),result_id uuid not null references public.tournament_results(id),unique(category_id,athlete_id,place));
create table public.audit_logs (id uuid primary key default gen_random_uuid(),tournament_id uuid references public.tournaments(id),actor_id uuid,action text not null,entity_type text not null,entity_id text not null,before_json jsonb,after_json jsonb,reason text,created_at timestamptz not null default now());
create table public.synchronization_jobs (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id),direction text not null,status text not null,last_event_id uuid,last_version bigint not null default 0,conflict_json jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index matches_live_cloud on public.matches(tournament_id,state,mat_id);
create index events_sequence_cloud on public.match_events(match_id,sequence);
create index proposals_consensus_cloud on public.scoring_proposals(match_id,round_id,side,point_type,status,submitted_at);
create index audit_time_cloud on public.audit_logs(tournament_id,created_at desc);

create or replace function public.is_tournament_admin(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from tournaments t join organization_members om on om.organization_id=t.organization_id where t.id=target and om.profile_id=auth.uid() and om.role in ('SUPER_ADMIN','TOURNAMENT_ADMIN'))$$;
create or replace function public.is_tournament_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from tournaments t join organization_members om on om.organization_id=t.organization_id where t.id=target and om.profile_id=auth.uid())$$;
create or replace function public.can_register(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from tournaments t join organization_members om on om.organization_id=t.organization_id where t.id=target and om.profile_id=auth.uid() and om.role in ('SUPER_ADMIN','TOURNAMENT_ADMIN','REGISTRATION_MANAGER'))$$;
create or replace function public.immutable_draw_version() returns trigger language plpgsql as $$begin raise exception 'Published draw versions are immutable';end$$;
create trigger immutable_draw_version before update or delete on public.draw_versions for each row execute function public.immutable_draw_version();
create or replace function public.append_only_event() returns trigger language plpgsql as $$begin raise exception 'Match events are append-only';end$$;
create trigger append_only_event before update or delete on public.match_events for each row execute function public.append_only_event();
create or replace function public.check_live_athlete_conflict() returns trigger language plpgsql as $$begin if new.state in ('CALLED','IN_PROGRESS','PAUSED','ROUND_BREAK','GOLDEN_POINT','UNDER_REVIEW') and exists(select 1 from matches m where m.id<>new.id and m.state in ('CALLED','IN_PROGRESS','PAUSED','ROUND_BREAK','GOLDEN_POINT','UNDER_REVIEW') and (m.blue_athlete_id in (new.blue_athlete_id,new.red_athlete_id) or m.red_athlete_id in (new.blue_athlete_id,new.red_athlete_id))) then raise exception 'Athlete is already in a simultaneous live match';end if;return new;end$$;
create trigger live_athlete_conflict before insert or update on public.matches for each row execute function public.check_live_athlete_conflict();

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,email,full_name) values(new.id,coalesce(new.email,''),coalesce(new.raw_user_meta_data->>'full_name',split_part(coalesce(new.email,''),'@',1))) on conflict(id) do nothing;return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

-- Public displays use this read-only view, never session/token tables.
-- Intentional fixed-schema definer view: expose display names without exposing athlete DOB, club contacts, or registration internals.
create or replace view public.public_match_display with(security_invoker=off) as select m.id,m.tournament_id,m.category_id,m.match_number,m.mat_id,m.state,m.current_round,m.blue_score,m.red_score,m.blue_gam_jeom,m.red_gam_jeom,m.winner_side,m.decision_method,m.sequence,m.updated_at,ba.first_name||' '||ba.last_name as blue_name,ba.country_code as blue_country_code,ra.first_name||' '||ra.last_name as red_name,ra.country_code as red_country_code from matches m left join athletes ba on ba.id=m.blue_athlete_id left join athletes ra on ra.id=m.red_athlete_id join tournaments t on t.id=m.tournament_id where t.status not in ('DRAFT','CANCELLED');
revoke all on public.public_match_display from public;
grant select on public.public_match_display to anon,authenticated;

alter table public.organizations enable row level security;alter table public.profiles enable row level security;alter table public.organization_members enable row level security;alter table public.tournaments enable row level security;alter table public.tournament_rulesets enable row level security;alter table public.clubs enable row level security;alter table public.athletes enable row level security;alter table public.athlete_registrations enable row level security;alter table public.weigh_ins enable row level security;alter table public.categories enable row level security;alter table public.tournament_seeds enable row level security;alter table public.mats enable row level security;alter table public.draws enable row level security;alter table public.draw_versions enable row level security;alter table public.brackets enable row level security;alter table public.bracket_nodes enable row level security;alter table public.matches enable row level security;alter table public.match_rounds enable row level security;alter table public.match_events enable row level security;alter table public.scoring_proposals enable row level security;alter table public.judge_sessions enable row level security;alter table public.referee_sessions enable row level security;alter table public.pairing_tokens enable row level security;alter table public.device_presence enable row level security;alter table public.match_assignments enable row level security;alter table public.tournament_results enable row level security;alter table public.medal_standings enable row level security;alter table public.audit_logs enable row level security;alter table public.synchronization_jobs enable row level security;
do $$begin if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='matches') then alter publication supabase_realtime add table public.matches;end if;end$$;
create policy "public published tournaments" on public.tournaments for select using(status not in ('DRAFT','CANCELLED') or is_tournament_member(id));
create policy "admins create tournaments" on public.tournaments for insert with check(exists(select 1 from organization_members om where om.organization_id=organization_id and om.profile_id=auth.uid() and om.role in ('SUPER_ADMIN','TOURNAMENT_ADMIN')));
create policy "admins update tournaments" on public.tournaments for update using(is_tournament_admin(id)) with check(is_tournament_admin(id));
create policy "members read rulesets" on public.tournament_rulesets for select using(is_tournament_member(tournament_id));
create policy "admins manage rulesets" on public.tournament_rulesets for all using(is_tournament_admin(tournament_id)) with check(is_tournament_admin(tournament_id));
create policy "member clubs" on public.clubs for select using(is_tournament_member(tournament_id));
create policy "registration clubs" on public.clubs for all using(can_register(tournament_id)) with check(can_register(tournament_id));
create policy "member athletes" on public.athletes for select using(is_tournament_member(tournament_id));
create policy "registration athletes" on public.athletes for all using(can_register(tournament_id)) with check(can_register(tournament_id));
create policy "public categories" on public.categories for select using(exists(select 1 from tournaments t where t.id=tournament_id and t.status not in ('DRAFT','CANCELLED')) or is_tournament_member(tournament_id));
create policy "admins categories" on public.categories for all using(is_tournament_admin(tournament_id)) with check(is_tournament_admin(tournament_id));
create policy "members registrations" on public.athlete_registrations for select using(is_tournament_member(tournament_id));
create policy "registration registrations" on public.athlete_registrations for all using(can_register(tournament_id)) with check(can_register(tournament_id));
create policy "registration weighins" on public.weigh_ins for all using(exists(select 1 from athlete_registrations r where r.id=registration_id and can_register(r.tournament_id))) with check(exists(select 1 from athlete_registrations r where r.id=registration_id and can_register(r.tournament_id)));
create policy "members seeds" on public.tournament_seeds for select using(exists(select 1 from categories c where c.id=category_id and is_tournament_member(c.tournament_id)));
create policy "admins seeds" on public.tournament_seeds for all using(exists(select 1 from categories c where c.id=category_id and is_tournament_admin(c.tournament_id))) with check(exists(select 1 from categories c where c.id=category_id and is_tournament_admin(c.tournament_id)));
create policy "members mats" on public.mats for select using(is_tournament_member(tournament_id));
create policy "admins mats" on public.mats for all using(is_tournament_admin(tournament_id)) with check(is_tournament_admin(tournament_id));
create policy "members draws" on public.draws for select using(exists(select 1 from categories c where c.id=category_id and is_tournament_member(c.tournament_id)));
create policy "admin draws" on public.draws for insert with check(exists(select 1 from categories c where c.id=category_id and is_tournament_admin(c.tournament_id)));
create policy "public draw versions" on public.draw_versions for select using(exists(select 1 from draws d join categories c on c.id=d.category_id where d.id=draw_id and (is_tournament_member(c.tournament_id) or d.status='PUBLISHED')));
create policy "admin publish versions" on public.draw_versions for insert with check(exists(select 1 from draws d join categories c on c.id=d.category_id where d.id=draw_id and is_tournament_admin(c.tournament_id)));
create policy "members brackets" on public.brackets for select using(exists(select 1 from categories c where c.id=category_id and is_tournament_member(c.tournament_id)));
create policy "admin brackets" on public.brackets for insert with check(exists(select 1 from categories c where c.id=category_id and is_tournament_admin(c.tournament_id)));
create policy "members bracket nodes" on public.bracket_nodes for select using(exists(select 1 from brackets b join categories c on c.id=b.category_id where b.id=bracket_id and is_tournament_member(c.tournament_id)));
create policy "public matches" on public.matches for select using(exists(select 1 from tournaments t where t.id=tournament_id and t.status not in ('DRAFT','CANCELLED')) or is_tournament_member(tournament_id));
create policy "public rounds" on public.match_rounds for select using(exists(select 1 from matches m where m.id=match_id and (is_tournament_member(m.tournament_id) or exists(select 1 from tournaments t where t.id=m.tournament_id and t.status not in ('DRAFT','CANCELLED')))));
create policy "members events" on public.match_events for select using(is_tournament_member(tournament_id));
create policy "members proposals" on public.scoring_proposals for select using(exists(select 1 from matches m where m.id=match_id and is_tournament_member(m.tournament_id)));
create policy "own profile" on public.profiles for select using(id=auth.uid());
create policy "own profile update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "member organizations" on public.organizations for select using(exists(select 1 from organization_members om where om.organization_id=id and om.profile_id=auth.uid()));
create policy "own memberships" on public.organization_members for select using(profile_id=auth.uid());
create policy "members results" on public.tournament_results for select using(is_tournament_member(tournament_id) or exists(select 1 from tournaments t where t.id=tournament_id and t.status not in ('DRAFT','CANCELLED')));
create policy "members medals" on public.medal_standings for select using(is_tournament_member(tournament_id) or exists(select 1 from tournaments t where t.id=tournament_id and t.status not in ('DRAFT','CANCELLED')));
create policy "members audit" on public.audit_logs for select using(is_tournament_member(tournament_id));
create policy "members assignments" on public.match_assignments for select using(exists(select 1 from matches m where m.id=match_id and is_tournament_member(m.tournament_id)));
-- No direct client INSERT/UPDATE/DELETE policies for matches, rounds, events, results, draws versions, sessions, or medals. Authorized server RPCs perform validated transactional mutations.

create or replace function public.ingest_local_event(p_event_id uuid,p_tournament_id uuid,p_match_id uuid,p_sequence bigint,p_event_type text,p_payload jsonb,p_idempotency_key text,p_server_timestamp bigint) returns jsonb language plpgsql security definer set search_path=public as $$declare current_sequence bigint;begin if coalesce(auth.jwt()->>'role','')<>'service_role' and not is_tournament_admin(p_tournament_id) then return jsonb_build_object('status','FORBIDDEN');end if;if exists(select 1 from match_events where event_id=p_event_id or (match_id=p_match_id and idempotency_key=p_idempotency_key)) then return jsonb_build_object('status','DUPLICATE');end if;select sequence into current_sequence from matches where id=p_match_id for update;if current_sequence is null then return jsonb_build_object('status','CONFLICT','reason','MATCH_NOT_IN_CLOUD');end if;if p_sequence<=current_sequence then return jsonb_build_object('status','CONFLICT','reason','SEQUENCE_CONFLICT','cloudSequence',current_sequence);end if;if p_sequence<>current_sequence+1 then return jsonb_build_object('status','CONFLICT','reason','SEQUENCE_GAP','cloudSequence',current_sequence);end if;insert into match_events(event_id,tournament_id,match_id,sequence,event_type,payload_json,idempotency_key,server_timestamp) values(p_event_id,p_tournament_id,p_match_id,p_sequence,p_event_type,p_payload,p_idempotency_key,p_server_timestamp);update matches set sequence=p_sequence,version=version+1,updated_at=now() where id=p_match_id;return jsonb_build_object('status','ACCEPTED');exception when unique_violation then return jsonb_build_object('status','DUPLICATE');end$$;
revoke all on function public.ingest_local_event(uuid,uuid,uuid,bigint,text,jsonb,text,bigint) from public,anon;
grant execute on function public.ingest_local_event(uuid,uuid,uuid,bigint,text,jsonb,text,bigint) to authenticated,service_role;

insert into storage.buckets(id,name,public) values('athlete-photos','athlete-photos',false),('club-logos','club-logos',true),('tournament-exports','tournament-exports',false) on conflict(id) do nothing;
create policy "club logo read" on storage.objects for select using(bucket_id='club-logos');
create policy "athlete photo read members" on storage.objects for select using(bucket_id='athlete-photos' and exists(select 1 from public.tournaments t where t.id::text=(storage.foldername(name))[1] and public.is_tournament_member(t.id)));
create policy "tournament export read members" on storage.objects for select using(bucket_id='tournament-exports' and exists(select 1 from public.tournaments t where t.id::text=(storage.foldername(name))[1] and public.is_tournament_member(t.id)));
-- Object paths begin with the tournament UUID. Writes use the server-only service role after membership and MIME/size validation.
